-- Permission vocabulary and system roles of the website module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the website permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('contact_message:read'::text, 'contact_message'::text, 'read'::text, 'Read contact message'::text),
            ('menu:read'::text, 'menu'::text, 'read'::text, 'Read menu'::text),
            ('menu_block:read'::text, 'menu_block'::text, 'read'::text, 'Read menu block'::text),
            ('page:read'::text, 'page'::text, 'read'::text, 'Read page'::text),
            ('page_block:read'::text, 'page_block'::text, 'read'::text, 'Read page block'::text),
            ('redirect:read'::text, 'redirect'::text, 'read'::text, 'Read redirect'::text),
            ('visitor:read'::text, 'visitor'::text, 'read'::text, 'Read visitor'::text),
            ('visitor_track:read'::text, 'visitor_track'::text, 'read'::text, 'Read visitor track'::text),
            ('website:read'::text, 'website'::text, 'read'::text, 'Read website'::text),
            ('website_member:read'::text, 'website_member'::text, 'read'::text, 'Read website member'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('contact_message:read'::text, 'contact_message'::text, 'read'::text, 'Read contact message'::text),
            ('menu:read'::text, 'menu'::text, 'read'::text, 'Read menu'::text),
            ('menu_block:read'::text, 'menu_block'::text, 'read'::text, 'Read menu block'::text),
            ('page:read'::text, 'page'::text, 'read'::text, 'Read page'::text),
            ('page_block:read'::text, 'page_block'::text, 'read'::text, 'Read page block'::text),
            ('redirect:read'::text, 'redirect'::text, 'read'::text, 'Read redirect'::text),
            ('visitor:read'::text, 'visitor'::text, 'read'::text, 'Read visitor'::text),
            ('visitor_track:read'::text, 'visitor_track'::text, 'read'::text, 'Read visitor track'::text),
            ('website:read'::text, 'website'::text, 'read'::text, 'Read website'::text),
            ('website_member:read'::text, 'website_member'::text, 'read'::text, 'Read website member'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
